'use client';

import { useCallback, useEffect, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { AppSidebar, type PageCounts } from './app-sidebar';
import {
  CURRENT_USER_ID,
  EMPTY_PAGES,
  NAV_GROUPS,
  NOTIFICATIONS,
  PEOPLE,
  PROJECTS,
  TASKS,
  WORKSPACES,
  personOf,
  type NavItem,
  type Notification,
  type PageId,
  type Project,
  type Task,
} from './data';
import {
  EmptyPageView,
  InboxPage,
  MembersPage,
  ProjectsPage,
  TaskListPage,
} from './page-views';
import type { CreateKind } from './quick-create-menu';
import { CommandPalette } from './search-palette';
import { TopBar } from './top-bar';

const NAV_ITEMS = NAV_GROUPS.flatMap((group) => group.items);

const FIRST_TASK_NUMBER = 100;

function navItemOf(pageId: PageId): NavItem {
  const item = NAV_ITEMS.find((candidate) => candidate.id === pageId);
  if (item) {
    return item;
  }
  return NAV_ITEMS[0];
}

function ancestorOf(pageId: PageId, workspaceName: string) {
  const group = NAV_GROUPS.find((candidate) =>
    candidate.items.some((item) => item.id === pageId)
  );
  if (group?.team) {
    return group.team.name;
  }
  if (group?.label) {
    return workspaceName;
  }
  return undefined;
}

function workspaceOf(workspaceId: string) {
  const workspace = WORKSPACES.find(
    (candidate) => candidate.id === workspaceId
  );
  if (workspace) {
    return workspace;
  }
  return WORKSPACES[0];
}

function numberOf(task: Task) {
  const digits = task.number.replace(/\D/g, '');
  return Number(digits);
}

function draftTaskAfter(tasks: Task[]): Task {
  const numbers = tasks.map(numberOf);
  const nextNumber = Math.max(FIRST_TASK_NUMBER, ...numbers) + 1;
  return {
    id: `task-${nextNumber}`,
    number: `LAT-${nextNumber}`,
    title: 'Untitled task',
    projectId: 'onboarding',
    assigneeId: CURRENT_USER_ID,
    due: 'No date',
    isDone: false,
  };
}

function draftProjectAfter(projects: Project[]): Project {
  const draftNumber = projects.length + 1;
  return {
    id: `project-${draftNumber}`,
    name: 'Untitled project',
    color: 'var(--muted-foreground)',
    leadId: CURRENT_USER_ID,
  };
}

function sidebarWidthOf(isCollapsed: boolean) {
  if (isCollapsed) {
    return 'w-10';
  }
  return 'w-60';
}

function isTypingTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  const isField = target.matches('input, textarea, select');
  return isField || target.isContentEditable;
}

function isPaletteShortcut(event: KeyboardEvent) {
  const isKKey = event.key.toLowerCase() === 'k';
  const hasModifier = event.metaKey || event.ctrlKey;
  return isKKey && hasModifier;
}

function isCreateShortcut(event: KeyboardEvent) {
  const isCKey = event.key.toLowerCase() === 'c';
  const hasModifier = event.metaKey || event.ctrlKey || event.altKey;
  const isTyping = isTypingTarget(event.target);
  return isCKey && !hasModifier && !isTyping;
}

export default function AppShells02() {
  const [activePageId, setActivePageId] = useState<PageId>('my-tasks');
  const [workspaceId, setWorkspaceId] = useState(WORKSPACES[0].id);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(true);
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);
  const [tasks, setTasks] = useState<Task[]>(TASKS);
  const [projects, setProjects] = useState<Project[]>(PROJECTS);
  const [notifications, setNotifications] =
    useState<Notification[]>(NOTIFICATIONS);

  const workspace = workspaceOf(workspaceId);
  const activePage = navItemOf(activePageId);
  const ancestor = ancestorOf(activePageId, workspace.name);
  const currentUser = personOf(CURRENT_USER_ID);
  const myTasks = tasks.filter((task) => task.assigneeId === CURRENT_USER_ID);
  const myOpenTasks = myTasks.filter((task) => !task.isDone);
  const teamOpenTasks = tasks.filter((task) => !task.isDone);
  const unreadNotifications = notifications.filter((note) => note.isUnread);
  const counts: PageCounts = {
    inbox: unreadNotifications.length,
    'my-tasks': myOpenTasks.length,
    'team-tasks': teamOpenTasks.length,
  };
  const emptyPage = EMPTY_PAGES[activePageId];

  const createTask = useCallback(() => {
    setTasks((previous) => {
      const draft = draftTaskAfter(previous);
      return [draft, ...previous];
    });
    setActivePageId('my-tasks');
  }, []);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (isPaletteShortcut(event)) {
        event.preventDefault();
        setIsPaletteOpen((isOpen) => !isOpen);
        return;
      }
      if (isCreateShortcut(event)) {
        event.preventDefault();
        createTask();
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [createTask]);

  function navigate(pageId: PageId) {
    setActivePageId(pageId);
    setIsNavigationOpen(false);
  }

  function create(kind: CreateKind) {
    setIsNavigationOpen(false);
    if (kind === 'task') {
      createTask();
      return;
    }
    if (kind === 'project') {
      setProjects((previous) => {
        const draft = draftProjectAfter(previous);
        return [...previous, draft];
      });
      setActivePageId('projects');
      return;
    }
    setActivePageId('members');
  }

  function createProject() {
    create('project');
  }

  function openSearch() {
    setIsNavigationOpen(false);
    setIsPaletteOpen(true);
  }

  function toggleSidebar() {
    setIsSidebarCollapsed((isCollapsed) => !isCollapsed);
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  function toggleTask(taskId: string) {
    setTasks((previous) =>
      previous.map((task) => {
        if (task.id !== taskId) {
          return task;
        }
        return { ...task, isDone: !task.isDone };
      })
    );
  }

  function readNotification(notificationId: string) {
    setNotifications((previous) =>
      previous.map((note) => {
        if (note.id !== notificationId) {
          return note;
        }
        return { ...note, isUnread: false };
      })
    );
  }

  function readAllNotifications() {
    setNotifications((previous) =>
      previous.map((note) => ({ ...note, isUnread: false }))
    );
  }

  const sidebarProps = {
    workspaces: WORKSPACES,
    workspace,
    onWorkspaceChange: setWorkspaceId,
    groups: NAV_GROUPS,
    activePageId,
    counts,
    person: currentUser,
    onNavigate: navigate,
    onOpenSearch: openSearch,
    onCreate: create,
  };

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-0 w-full md:p-2'>
      <aside aria-label='Sidebar' className='hidden shrink-0 md:block'>
        <AnimatedSize
          axis='width'
          className='m-0 h-full'
          contentClassName='h-full p-0'
        >
          <div
            className={cn('h-full pr-2', sidebarWidthOf(isSidebarCollapsed))}
          >
            <AppSidebar {...sidebarProps} isCollapsed={isSidebarCollapsed} />
          </div>
        </AnimatedSize>
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Navigation</SheetTitle>
          <AppSidebar {...sidebarProps} isCollapsed={false} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <TopBar
          page={activePage}
          ancestor={ancestor}
          people={PEOPLE}
          isSidebarCollapsed={isSidebarCollapsed}
          onToggleSidebar={toggleSidebar}
          onOpenNavigation={openNavigation}
        />
        {activePageId === 'inbox' && (
          <InboxPage
            notifications={notifications}
            onRead={readNotification}
            onReadAll={readAllNotifications}
          />
        )}
        {activePageId === 'my-tasks' && (
          <TaskListPage
            key='my-tasks'
            title='My tasks'
            tasks={myTasks}
            showAssignee={false}
            onToggleTask={toggleTask}
            onCreateTask={createTask}
          />
        )}
        {activePageId === 'team-tasks' && (
          <TaskListPage
            key='team-tasks'
            title='Product tasks'
            tasks={tasks}
            showAssignee
            onToggleTask={toggleTask}
            onCreateTask={createTask}
          />
        )}
        {activePageId === 'projects' && (
          <ProjectsPage
            projects={projects}
            tasks={tasks}
            onCreateProject={createProject}
          />
        )}
        {activePageId === 'members' && <MembersPage people={PEOPLE} />}
        {emptyPage && (
          <EmptyPageView
            title={activePage.label}
            icon={activePage.icon}
            page={emptyPage}
          />
        )}
      </main>
      <CommandPalette
        open={isPaletteOpen}
        onOpenChange={setIsPaletteOpen}
        groups={NAV_GROUPS}
        onNavigate={navigate}
        onCreateTask={createTask}
      />
    </div>
  );
}

'use client';

import { motion, useReducedMotion } from 'motion/react';
import { useId } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { AccountMenu } from './account-menu';
import type { NavGroup, NavItem, PageId, Person, Workspace } from './data';
import { QuickCreateMenu, type CreateKind } from './quick-create-menu';
import { SearchTrigger } from './search-palette';
import { EntityTile, NavRow, morphOf } from './sidebar-parts';
import { WorkspaceSwitcher } from './workspace-switcher';

export type PageCounts = Partial<Record<PageId, number>>;

type AppSidebarProps = {
  workspaces: Workspace[];
  workspace: Workspace;
  onWorkspaceChange: (workspaceId: string) => void;
  groups: NavGroup[];
  activePageId: PageId;
  counts: PageCounts;
  person: Person;
  isCollapsed: boolean;
  onNavigate: (pageId: PageId) => void;
  onOpenSearch: () => void;
  onCreate: (kind: CreateKind) => void;
};

function labelTextOf(group: NavGroup) {
  if (group.team) {
    return group.team.name;
  }
  return group.label;
}

function GroupLabel({
  group,
  isCollapsed,
}: {
  group: NavGroup;
  isCollapsed: boolean;
}) {
  const labelText = labelTextOf(group);
  if (!labelText) {
    return null;
  }

  return (
    <p className='text-muted-foreground flex h-6 items-center gap-2 px-2 text-xs font-medium'>
      {group.team && <EntityTile entity={group.team} size='xs' />}
      <span className={cn('truncate', isCollapsed && 'sr-only')}>
        {labelText}
      </span>
    </p>
  );
}

export function AppSidebar({
  workspaces,
  workspace,
  onWorkspaceChange,
  groups,
  activePageId,
  counts,
  person,
  isCollapsed,
  onNavigate,
  onOpenSearch,
  onCreate,
}: AppSidebarProps) {
  const indicatorId = useId();
  const shouldReduceMotion = useReducedMotion();
  const morph = morphOf(shouldReduceMotion);

  function selectItem(item: NavItem) {
    onNavigate(item.id);
  }

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <motion.div layout='position' transition={morph} className='flex'>
          <WorkspaceSwitcher
            workspaces={workspaces}
            current={workspace}
            isCollapsed={isCollapsed}
            onSelect={onWorkspaceChange}
          />
        </motion.div>
        <div className={cn('flex gap-2', isCollapsed && 'flex-col')}>
          <motion.div
            layout='position'
            transition={morph}
            className='flex min-w-0 flex-1'
          >
            <SearchTrigger isCollapsed={isCollapsed} onOpen={onOpenSearch} />
          </motion.div>
          <motion.div layout='position' transition={morph} className='flex'>
            <QuickCreateMenu isCollapsed={isCollapsed} onCreate={onCreate} />
          </motion.div>
        </div>
      </div>
      <motion.nav
        layout='position'
        transition={morph}
        aria-label='Main'
        className='-mx-2 flex min-h-0 flex-1 flex-col gap-4 overflow-x-hidden overflow-y-auto px-2'
      >
        {groups.map((group) => (
          <div key={group.id} className='flex flex-col gap-0.5'>
            <GroupLabel group={group} isCollapsed={isCollapsed} />
            <ul className='flex flex-col gap-px'>
              {group.items.map((item) => (
                <NavRow
                  key={item.id}
                  item={item}
                  isActive={item.id === activePageId}
                  isCollapsed={isCollapsed}
                  indicatorId={indicatorId}
                  count={counts[item.id]}
                  onSelect={selectItem}
                />
              ))}
            </ul>
          </div>
        ))}
      </motion.nav>
      <AccountMenu person={person} isCollapsed={isCollapsed} />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

import type { Entity, NavItem, Person } from './data';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

/** The spring of the rail morph, the same as the width of the sidebar. */
const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INDICATOR_RADIUS = { borderRadius: 6 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

/** The one highlight of the active row. It travels from the old row to the new one and morphs with the rail. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layout
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      style={INDICATOR_RADIUS}
      className='bg-foreground/[0.07] absolute inset-0'
    />
  );
}

const COUNT_SHIFT_PX = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const COUNT_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * COUNT_SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * COUNT_SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

type CountState = { value: number; direction: number };

function countVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return COUNT_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

export function SlidingCount({
  value,
  className,
}: {
  value: number;
  className?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [shown, setShown] = useState<CountState>({ value, direction: 1 });
  const variants = countVariantsOf(shouldReduceMotion);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={value}
          custom={shown.direction}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={COUNT_TRANSITION}
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const TILE_SIZE = {
  xs: 'size-4 rounded-[4px] text-[9px]',
  sm: 'size-5 rounded-[5px] text-[10px]',
  md: 'size-6 rounded-md text-[11px]',
} as const;

export function EntityTile({
  entity,
  size = 'md',
  className,
}: {
  entity: Entity;
  size?: keyof typeof TILE_SIZE;
  className?: string;
}) {
  const tileStyle = { '--gem': entity.color } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={tileStyle}
      className={cn(
        'gem-plate inline-flex shrink-0 items-center justify-center font-semibold',
        TILE_SIZE[size],
        className
      )}
    >
      {entity.initials}
    </span>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={className}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

type NavRowProps = {
  item: NavItem;
  isActive: boolean;
  isCollapsed: boolean;
  indicatorId: string;
  count?: number;
  onSelect: (item: NavItem) => void;
};

export function NavRow({
  item,
  isActive,
  isCollapsed,
  indicatorId,
  count = 0,
  onSelect,
}: NavRowProps) {
  const hasCount = count > 0;
  const showsCount = hasCount && !isCollapsed;
  const showsCountDot = hasCount && isCollapsed;
  const ItemIcon = item.icon;
  const ariaCurrent = ariaCurrentOf(isActive);

  function selectItem() {
    onSelect(item);
  }

  return (
    <li>
      <Tooltip disabled={!isCollapsed}>
        <TooltipTrigger
          type='button'
          aria-current={ariaCurrent}
          onClick={selectItem}
          className={NAV_ROW}
        >
          {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
          <span className='relative flex'>
            <ItemIcon />
            {showsCountDot && (
              <span className='bg-primary ring-sidebar absolute -top-0.5 -right-0.5 size-1.5 rounded-full ring-2' />
            )}
          </span>
          <span
            className={cn(
              'relative min-w-0 flex-1 truncate',
              isCollapsed && 'sr-only'
            )}
          >
            {item.label}
            {showsCountDot && <span>{`, ${count}`}</span>}
          </span>
          {showsCount && (
            <SlidingCount
              value={count}
              className='text-muted-foreground text-xs font-normal'
            />
          )}
        </TooltipTrigger>
        <TooltipContent side='right' className='flex items-center gap-2'>
          {item.label}
          {hasCount && (
            <span className='text-muted-foreground tabular-nums'>{count}</span>
          )}
        </TooltipContent>
      </Tooltip>
    </li>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Workspace } from './data';
import { EntityTile } from './sidebar-parts';

const TRIGGER = [
  'flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md px-1 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

type WorkspaceSwitcherProps = {
  workspaces: Workspace[];
  current: Workspace;
  isCollapsed: boolean;
  onSelect: (workspaceId: string) => void;
};

export function WorkspaceSwitcher({
  workspaces,
  current,
  isCollapsed,
  onSelect,
}: WorkspaceSwitcherProps) {
  function selectWorkspace(value: unknown) {
    if (typeof value === 'string') {
      onSelect(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Workspace: ${current.name}`}
            className={TRIGGER}
          />
        }
      >
        <EntityTile entity={current} />
        {!isCollapsed && (
          <>
            <span className='min-w-0 flex-1 truncate text-[13px] font-semibold'>
              {current.name}
            </span>
            <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
          </>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-64'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={current.id}
          onValueChange={selectWorkspace}
        >
          {workspaces.map((workspace) => (
            <DropdownMenuRadioItem
              key={workspace.id}
              value={workspace.id}
              closeOnClick
              className='h-9'
            >
              <EntityTile entity={workspace} size='sm' />
              <span className='min-w-0 flex-1 truncate'>{workspace.name}</span>
              <Kbd aria-hidden='true'>{workspace.memberCount}</Kbd>
              <span className='sr-only'>
                {memberCountLabelOf(workspace.memberCount)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <SettingsIcon />
          Workspace settings
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Add workspace
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { CircleCheckIcon, SearchIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from '@/registry/ndeko/ui/command';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import {
  Tooltip,
